 <div class="dots">${CARDS.map((_,i)=>`<i class="${i<S.i?"d":""}"></i>`).join("")}</div></div>`};

V.dna=()=>{if(!S.dna)return V.swipe();const rows=Object.keys(DIMS).map(k=>[k,Math.round(S.dna[k]*100)]).sort((a,b)=>b[1]-a[1]);
