 <div class="row" style="margin-top:.6rem"><button class="btn alt" data-a="offline" data-id="${b.id}">${S.saved[b.id]?"Saved offline âœ“":"Save offline"}</button><button class="btn alt" data-a="go" data-s="card">âœï¸ Leave a postcard</button></div>
