 m=s.match(/(\d{2,4})\s*(?:[.,]000|ribu|rb)/);if(m)o.price="Rp"+m[1]+".000 per person";
 m=s.match(/(\d+|satu|dua|tiga|empat|lima|enam)\s*jam/);if(m)o.duration="About "+(num[m[1]]||m[1])+" hours";
