 if(acts.length)o.activities=acts.join(", ");
 const days=[["senin","Monday"],["selasa","Tuesday"],["rabu","Wednesday"],["kamis","Thursday"],["jumat","Friday"],["sabtu","Saturday"],["minggu","Sunday"]].filter(d=>s.includes(d[0])).map(d=>d[1]);
