        )


# ------------------------------------------------------------
# EXPERIENCES
# ------------------------------------------------------------

@app.get("/api/experiences")
def get_experiences(
    business_id: str | None = None,
):
    """Return active experiences.

    Optional:
        ?business_id=<uuid>
    """

    try:
        query = (
            supabase
            .table("experiences")
            .select("*")
