# ------------------------------------------------------------
# POSTCARDS
# ------------------------------------------------------------

@app.get("/api/postcards")
def get_postcards(
    experience_id: str | None = None,
):
    """Return postcards from Supabase.

    Optional:
        ?experience_id=<uuid>
    """

    try:
        query = (
            supabase
            .table("postcards")
            .select("*")
        )

        if experience_id:
            query = query.eq(
                "experience_id",
                experience_id,
            )

        result = (
            query
            .order(
                "created_at",
                desc=True,
            )
            .execute()
        )

